    {
      "id": "retag-images",
      "description": "Retag images with ECR repository URI",
      "action": "retag",
      "target": "ecr",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Images have been pulled",
          "fact": "images_pulled",
          "established_by": "pull-images"
        }
      ]
    },
    {
      "id": "push-images",
      "description": "Push retagged images to Amazon ECR",
      "action": "push",
      "target": "ecr",
      "risk_class": "high",
      "rollback": {
        "trigger": "push fails",
        "action": "notify administrator",
        "safety_guard": "check ECR access permissions"
      },
      "verification": {
        "what": "image presence in ECR",
        "how": "list repository images",
        "expected": "images are successfully pushed"
      },
      "preconditions": [
        {
          "description": "Images have been retagged",
          "fact": "images_retaged",
          "established_by": "retag-images"
