      "preconditions": [
        {
          "description": "Images have been pushed to ECR",
          "fact": "images_pushed",
          "established_by": "push-images"
        }
      ]
    },
    {
      "id": "rollout-restart",
      "description": "Trigger rolling restart of deployments and stateful sets",
      "action": "rollout restart",
      "target": "k8s_resources",
      "risk_class": "critical",
      "rollback": {
        "trigger": "restart fails",
        "action": "revert to previous image",
        "safety_guard": "ensure old images are retained"
      },
      "verification": {
        "what": "pod readiness",
        "how": "check pod statuses",
        "expected": "all pods are running and ready"
      },
      "preconditions": [
        {
          "description": "Manifests have been updated",
          "fact": "manifests_updated",
          "established_by": "update-manifests"
        }
      ]
    },
    {
      "id": "verify-traffic",
      "description": "Verify that every service pod pulls successfully from ECR and serves traffic normally",
      "action": "check",
      "target": "service_traffic",
      "risk_class": "high",
      "rollback": {
        "trigger": "traffic issues detected",
        "action": "rollback to Docker Hub images",
        "safety_guard": "ensure rollback script is ready"
      },
      "verification": {
        "what": "service response",
        "how": "query each service endpoint",
        "expected": "services respond successfully"
      },
      "preconditions": [
        {
          "description": "Rolling restart has been completed",
          "fact": "restart_complete",
          "established_by": "rollout-restart"
        }
      ]
    }
  ],
  "dependencies": [
    {
      "from_task": "pull-images",
      "to_task": "retag-images",
      "kind": "hard"
    },
    {
      "from_task": "retag-images",
      "to_task": "push-images",
      "kind": "hard"
    },
    {
      "from_task": "push-images",
      "to_task": "update-manifests",
      "kind": "hard"
    },
    {
      "from_task": "update-manifests",
      "to_task": "rollout-restart",
      "kind": "hard"
    },
    {
      "from_task": "rollout-restart",
      "to_task": "verify-traffic",
      "kind": "hard"
    }
  ],
  "branches": [
    {
      "id": "rollback-branch",
      "kind": "rollback",
      "tasks": [
        {
          "id": "rollback-images",
          "description": "Maintain old Docker Hub references",
          "action": "branch",
          "target": "docker_hub",
          "risk_class": "medium",
          "preconditions": []
        }
      ],
      "join": "verify-traffic"
    }
  ]
}

